package com.careerpilot.backend.modules.application.domain;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.*; import java.util.*;
@Entity @Table(name="application_approval_policies") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor public class ApprovalPolicy { @Id private UUID id; @Column(name="candidate_id",nullable=false,unique=true) private UUID candidateId; @Enumerated(EnumType.STRING) @Column(nullable=false) @Builder.Default private ApprovalMode mode=ApprovalMode.MANUAL; @Column(name="minimum_score") private Double minimumScore; @Column(name="require_remote") private Boolean requireRemote; private String technology; private String location; @Convert(converter = com.careerpilot.backend.config.JsonMapConverter.class) @Column(name="rules",columnDefinition="text") @Builder.Default private Map<String,Object> rules=new HashMap<>(); @Column(name="updated_at",nullable=false) private Instant updatedAt; }
